const PIE_METRICS=[['r','Runs'],['w','Wickets'],['m','Matches'],['h','100s'],['f','50s'],['s4','4s'],['s6','6s']];
function pieDataPlayer(){
 const base=S.players.filter(p=>!pteam||playerTeams(p).includes(+pteam)),rows=base.map(p=>[p.n,statValue(p,pieFmt,pteam||'',pieMetric),p.id]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);
 if(rows.length<=7)return rows.map(x=>[x[0],x[1]]);
 const top=rows.slice(0,6),other=rows.slice(6).reduce((s,x)=>s+x[1],0);return [...top.map(x=>[x[0],x[1]]),['Other players',other]];
}
function pieDataTeams(){
 const rows=S.teams.map(tm=>[tm.n,S.players.reduce((n,p)=>n+(playerTeams(p).includes(tm.id)?statValue(p,pieFmt,tm.id,pieMetric):0),0),tm.id]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);
 if(rows.length<=7)return rows.map(x=>[x[0],x[1]]);
 const top=rows.slice(0,6),other=rows.slice(6).reduce((s,x)=>s+x[1],0);return [...top.map(x=>[x[0],x[1]]),['Other teams',other]];
}
function pieMetricLabel(){const x=PIE_METRICS.find(z=>z[0]==pieMetric);return x?x[1]:pieMetric}

function showPieInsights(kind,label,value,data){
 const total=data.reduce((s,x)=>s+x[1],0);
 const pct=total?((value/total)*100):0;
 const title=kind==='players'?'Players Insights & Analytics':'Teams Insights & Analytics';
 const scope=`${pieFmt==='T20I'?'T20':pieFmt} · ${pieMetricLabel()}`;
 const rows=data.map(x=>`<div class="insight-row"><span class="font-semibold">${esc(x[0])}</span><b>${x[1]} <span class="text-xs" style="color:var(--mut)">(${((x[1]/total)*100).toFixed(1)}%)</span></b></div>`).join('');
 modal(`<div class="mb-4"><div class="text-xs font-extrabold uppercase tracking-wider" style="color:var(--mut)">${title}</div><h3 class="text-2xl font-extrabold mt-1">${esc(label)}</h3><p class="text-sm mt-1" style="color:var(--mut)">${value} of ${total} total · ${pct.toFixed(1)}% · ${scope}</p></div><div class="card p-4">${rows}</div><div class="mt-4 text-sm" style="color:var(--mut)">Tap another slice to compare its share. Values are calculated from the current UNITED KERALAM database.</div>`);
}
function drawPie(id,kind,data){
 const c=document.getElementById(id); if(!c||!window.Chart)return;
 if(pieCharts[id])pieCharts[id].destroy();
 pieCharts[id]=new Chart(c,{type:'doughnut',data:{labels:data.map(x=>x[0]),datasets:[{data:data.map(x=>x[1]),borderWidth:2,hoverOffset:10}]},
 options:{responsive:true,maintainAspectRatio:false,cutout:'58%',plugins:{legend:{position:'bottom',labels:{boxWidth:12,padding:14,usePointStyle:true,color:gc()}}},
 onClick:(evt,elements)=>{if(!elements.length)return;const i=elements[0].index;showPieInsights(kind,data[i][0],data[i][1],data)}}});
}
function renderPieCharts(){
 const pd=pieDataPlayer(),td=pieDataTeams();
 drawPie('playersPie','players',pd);
 drawPie('teamsPie','teams',td);
}

