function setImgUrl(key,v){v=v.trim();if(v&&!/^(https?:\/\/|data:image\/)/i.test(v))return;$('#f_'+key).value=v;const pv=$('#pv_'+key);if(v){pv.src=v;pv.classList.remove('hidden')}else pv.classList.add('hidden')}
function readImg(el,key){const f=el.files[0];if(!f)return;if(f.size>4e6)return alert('Image too large (max 4 MB)');const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,(key=='photo'?640:256)/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);const u=c.toDataURL('image/webp',.75);$('#f_'+key).value=u;const pv=$('#pv_'+key);pv.src=u;pv.classList.remove('hidden')};im.src=fr.result};fr.readAsDataURL(f)}
const tav=(x,c='w-16 h-16')=>x.logo?`<img src="${x.logo}" class="${c} object-contain">`:`<div class="av ${c} text-xl">${ini(x.n)}</div>`;
const trophyWinYears=y=>{const raw=String(y??'').trim();if(!raw)return[];return raw.split(/[,|]+/).map(v=>v.trim()).filter(Boolean)};
const trophyWinCount=L=>L.reduce((n,z)=>n+trophyWinYears(z.y).length,0);
const trophyDisplayYears=L=>L.flatMap(z=>trophyWinYears(z.y));
const tournamentForTrophy=z=>{const n=norm(z?.n||'');if(!n)return null;const ys=trophyWinYears(z?.y);const L=[...S.tours].sort((a,b)=>(+b.y||0)-(+a.y||0));return L.find(t=>ys.includes(String(t.y))&&(()=>{const q=norm(t.n);return q===n||n.includes(q)||q.includes(n)})())||L.find(t=>{const q=norm(t.n);return q===n||n.includes(q)||q.includes(n)})||null};
const trophyLink=z=>{const tr=tournamentForTrophy(z);return tr?`#/tour/${tr.id}/trophy`:''};
const openTrophyTournament=(zid)=>{const z=(S.trophies||[]).find(x=>x.id==zid);const tr=tournamentForTrophy(z);if(!tr){alert('This trophy is not linked to an individual tournament yet. In Edit mode, make the trophy/cup name match the tournament name.');return false}ttab='trophy';location.hash=`#/tour/${tr.id}/trophy`;return true};
const stopTrophyNav=e=>{if(e){e.preventDefault();e.stopPropagation()}};
const TRO=tid=>{
 const G={};
 (S.trophies||[]).filter(z=>z.tid==tid).forEach(z=>(G[z.n]=G[z.n]||[]).push(z));
 return Object.entries(G).map(([n,L])=>{
  L.sort((a,b)=>String(a.y).localeCompare(String(b.y)));
  const years=trophyDisplayYears(L),wins=trophyWinCount(L),ic=L.find(z=>z.img),ph=[...L].reverse().find(z=>z.photo),np=L.filter(z=>z.photo).length,linked=tournamentForTrophy(L[0]);
  return`<div class="card flex items-stretch overflow-hidden mb-4 cursor-pointer" style="min-height:140px" onclick="openTrophyTournament(${L[0].id})" title="${linked?'Open '+esc(linked.n)+' trophy profile':'Open tournament trophy profile'}"><div class="flex items-center gap-4 sm:gap-8 flex-1 min-w-0 p-4 sm:p-6"><div class="w-14 sm:w-20 shrink-0 text-center">${ic?`<img src="${esc(ic.img)}" class="max-h-24 mx-auto object-contain">`:'<span class="text-5xl">🏆</span>'}</div><div class="trn">${wins}</div><div class="min-w-0"><div class="text-lg sm:text-xl font-extrabold">${linked?`<a class="plain-link" href="#/tour/${linked.id}/trophy" onclick="stopTrophyNav(event);openTrophyTournament(${L[0].id})">${esc(n)} ↗</a>`:esc(n)}</div><div class="flex flex-wrap gap-x-3 gap-y-1 text-sm mt-2" style="color:var(--mut)">${years.map(y=>{const z=L.find(v=>trophyWinYears(v.y).includes(y));return trophyLink(z)?`<a class="plain-link" href="${trophyLink(z)}" onclick="stopTrophyNav(event);openTrophyTournament(${z.id})">${esc(y)}</a>`:`<span>${esc(y)}</span>`}).join('')}</div><div class="mt-2 flex flex-wrap gap-2">${L.map(z=>`<button class="text-xs font-bold" onclick="stopTrophyNav(event);trophyForm(${z.tid},${z.id})">${esc(z.y)} ✎</button><button class="text-xs font-bold" onclick="stopTrophyNav(event);trophyDel(${z.id})">✕</button>`).join('')}</div></div></div>${ph?`<div class="relative w-28 sm:w-64 shrink-0"><img src="${esc(ph.photo)}" class="absolute inset-0 w-full h-full object-cover">${np>1?`<span class="absolute top-3 right-3 bg-white text-[#00195f] rounded-full px-3 py-1 text-sm font-bold">🖼 +${np-1}</span>`:''}</div>`:''}</div>`}).join('')||'<p class="text-sm">No trophies yet. Turn on Edit mode to add one.</p>';
};
const trackYears=tid=>{
 const rows=[];
 (S.trophies||[]).filter(z=>z.tid==tid).forEach(z=>trophyWinYears(z.y).forEach(y=>rows.push({year:String(y),name:z.n,id:z.id,img:z.img||'',photo:z.photo||''})));
 const map={};rows.forEach(r=>(map[r.year]=map[r.year]||[]).push(r));
 return Object.entries(map).sort((a,b)=>Number(b[0])-Number(a[0]));
};
const legendaryTrack=tid=>{
 const x=T(tid),groups=trackYears(tid),all=(S.trophies||[]).filter(z=>z.tid==tid),wins=trophyWinCount(all),uniqueYears=groups.length;
 const trophyGroups=[...new Set(all.map(z=>z.n))];
 const byName={};all.forEach(z=>(byName[z.n]=byName[z.n]||[]).push(z));
 const stats=trophyGroups.map(n=>({n,w:trophyWinCount(byName[n])})).sort((a,b)=>b.w-a.w);
 const hero=all.filter(z=>z.photo||z.img).slice(-1)[0];
 return`<section class="legend-track mb-7"><div class="legend-track-grid"><div class="legend-track-photo">${hero?.photo?`<img src="${esc(hero.photo)}" alt="">`:hero?.img?`<img src="${esc(hero.img)}" alt="">`:`<div class="h-full grid place-items-center text-[120px]">🏆</div>`}<div class="absolute left-5 bottom-5 z-10"><div class="text-xs font-extrabold tracking-[.22em] uppercase opacity-80">A LEGENDARY TRACK RECORD</div><div class="text-3xl md:text-5xl font-extrabold mt-1">${esc(x.n)}</div></div></div><div class="legend-track-side"><div class="text-xs font-extrabold tracking-[.18em] text-[#cbd8f4] mb-3">HONOURS THROUGH THE YEARS</div><div class="legend-stat-grid"><div class="legend-stat"><b>${wins}</b><span>TROPHY WINS</span></div><div class="legend-stat"><b>${uniqueYears}</b><span>WINNING YEARS</span></div>${stats.slice(0,6).map(s=>`<div class="legend-stat"><b>${s.w}</b><span>${esc(s.n.toUpperCase())}</span></div>`).join('')}</div></div></div></section>
 <div class="flex flex-wrap justify-between items-center gap-3 mb-4"><div><h2 class="text-2xl font-extrabold">TROPHY TIMELINE</h2><p class="text-sm mt-1" style="color:var(--mut)">Every year shows the trophies won by this team.</p></div><button class="btn" onclick="trophyForm(${tid})">+ Add trophy win</button></div>
 <div class="track-timeline">${groups.map(([year,L])=>`<article class="track-year"><div class="track-year-card"><div class="flex flex-wrap justify-between items-center gap-3"><div class="track-year-num">${esc(year)}</div><span class="text-xs font-extrabold" style="color:var(--mut)">${L.length} win${L.length===1?'':'s'}</span></div><div class="flex flex-wrap gap-2 mt-4">${L.map(r=>{const tr=tournamentForTrophy(r);return`<span class="track-award-chip cursor-pointer" onclick="openTrophyTournament(${r.id})" title="${tr?'Open '+esc(tr.n)+' trophy profile':'Open tournament trophy profile'}">🏆 ${tr?`<a class="plain-link" href="#/tour/${tr.id}/trophy" onclick="stopTrophyNav(event);openTrophyTournament(${r.id})">${esc(r.name)} ↗</a>`:esc(r.name)} <button class="font-black" title="Edit" onclick="stopTrophyNav(event);trophyForm(${tid},${r.id})">✎</button><button class="font-black" title="Delete" onclick="stopTrophyNav(event);trophyDel(${r.id})">×</button></span>`}).join('')}</div></div></article>`).join('')||`<div class="card p-8 text-center" style="color:var(--mut)">No trophy wins yet. Use “Add trophy win” to build the timeline.</div>`}</div>
 <div class="mt-8"><h2 class="text-xl font-extrabold mb-3">TROPHY CATEGORIES</h2>${TRO(tid)}</div>`;
};
function editTeam(id){const x=T(id);guard(()=>form('Edit team',teamFields(x),d=>{const b=teamPayload(d);b.name=b.name||x.n;if(ON)return run(api('/api/teams/'+id,'PUT',b));Object.assign(x,{n:b.name,...b,logo:b.logo||''});save();render()}))}
function trophyForm(tid,id){
 const x=id!=null?S.trophies.find(z=>z.id==id):{n:'',y:String(new Date().getFullYear()),img:'',photo:''};
 guard(()=>form(id!=null?'Edit trophy win':'Add trophy win',[['Trophy / cup name','n',x.n],['Year(s) won','y',x.y],['Trophy / cup image','img',x.img||'','img'],['Celebration photo','photo',x.photo||'','img']],d=>{
  if(!d.n.trim()||!String(d.y).trim())throw new Error('Trophy name and year are required');
  const years=trophyWinYears(d.y).join(', '),b={team_id:tid,name:d.n.trim(),year:years,img:d.img||null,photo:d.photo||null};
  if(ON)return run(id!=null?api('/api/trophies/'+id,'PUT',b):api('/api/trophies','POST',b));
  if(id!=null)Object.assign(x,{n:b.name,y:b.year,img:d.img||'',photo:d.photo||''});else S.trophies.push({id:Date.now(),tid,n:b.name,y:b.year,img:d.img||'',photo:d.photo||''});
  save();render();
 }))}
function trophyDel(id){guard(()=>{if(confirm('Delete this trophy win?')){if(ON)return run(api('/api/trophies/'+id,'DELETE')).then(render);S.trophies=S.trophies.filter(z=>z.id!=id);save();render()}})}
