/* ---- tickets ---- */
const CATM={General:1,Premium:2,VIP:4},VEN=['Kozhikode','Kochi','Trivandrum','Munnar','Wayanad'];let tv='',unlocked=false,IMP=null;
const tprice=(m,c)=>Math.round(m.base*CATM[c]*(1+m.hype/100*.8)*(1+m.sold/m.cap*.75)/10)*10;
const fdate=d=>{try{return new Date(String(d).replace(' ','T')).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}catch{return d}};
const seedMatches=()=>{let d=0;return VEN.flatMap((v,vi)=>[0,1].map(k=>{const h=hash(v+k),home=S.teams.find(x=>x.n==(v=='Kochi'?'Cochin':v))||S.teams[0],o=S.teams.filter(x=>x.id!=home.id),away=o[h%o.length],cap=8000+(h%5)*4000;return{id:400+vi*2+k,v,a:home.id,b:away.id,d:'2026-10-'+String(10+d++*2).padStart(2,'0')+' 19:00',fm:['T20I','ODI','T20I'][h%3],base:300+(h%6)*100,cap,sold:Math.round(cap*(.2+(h%50)/100)),hype:40+(h%60)}}))};
function book(id){if(!ME)return auth();const m=S.matches.find(x=>x.id==id);modal(`<h3 class="text-xl font-extrabold mb-1">${T(m.a)?.n} vs ${T(m.b)?.n}</h3><p class="text-sm mb-4" style="color:var(--mut)">${m.v} · ${fdate(m.d)}</p><div class="space-y-3"><select id="bc" onchange="bcalc(${id})">${Object.keys(CATM).map(c=>`<option value="${c}">${c} — ₹${tprice(m,c)}</option>`).join('')}</select><input id="bq" type="number" min="1" max="10" value="2" oninput="bcalc(${id})"><div class="text-lg font-extrabold" id="bt"></div><p class="text-xs" style="color:var(--mut)">Reservation only — online payment is not connected yet.</p><button class="btn w-full" onclick="bconf(${id})">Confirm booking</button><button class="btn o w-full" onclick="closeM()">Cancel</button></div>`);bcalc(id)}
function bcalc(id){const m=S.matches.find(x=>x.id==id),n=Math.max(1,Math.min(10,+$('#bq').value||1));$('#bt').textContent='Total ₹'+tprice(m,$('#bc').value)*n}
async function bconf(id){const m=S.matches.find(x=>x.id==id),c=$('#bc').value,n=Math.max(1,Math.min(10,Math.round(+$('#bq').value||1)));if(m.sold+n>m.cap)return alert('Not enough seats left');
 try{if(ON){await api('/api/bookings','POST',{match_id:id,category:c,qty:n});await load()}else{const amt=tprice(m,c)*n;m.sold+=n;(S.bookings=S.bookings||[]).push({id:Date.now(),mid:id,cat:c,qty:n,amount:amt,at:new Date().toISOString()});save()}closeM();render();alert('Booked! See My bookings on this page.')}catch(e){alert(e.message)}}
function matchForm(id,presetVenue){const m=id!=null?S.matches.find(x=>x.id==id):{v:presetVenue||'Kozhikode',a:S.teams[0]?.id,b:(S.teams[1]||S.teams[0])?.id,d:'2026-11-01 19:00',fm:'T20I',base:400,cap:15000,sold:0,hype:60};guard(()=>form(id!=null?t('edit_ticket'):t('add_ticket'),[[t('venue'),'v',m.v],[t('home_team'),'a',m.a,teamOpts()],[t('away_team'),'b',m.b,teamOpts()],[t('date')+' & time (YYYY-MM-DD HH:MM)','d',m.d],[t('format'),'fm',m.fm,F.map(x=>[x,x])],[t('price')+' (₹)','base',m.base],[t('capacity'),'cap',m.cap],[t('sold')+' '+t('tickets'),'sold',m.sold],[t('hype')+' (0-100)','hype',m.hype]],d=>{const cap=Math.max(1,Math.round(+d.cap||1000)),sold=Math.max(0,Math.min(cap,Math.round(+d.sold||0)));const v={v:d.v,a:+d.a,b:+d.b,d:d.d,fm:d.fm,base:+d.base||300,cap,sold,hype:Math.max(0,Math.min(100,+d.hype||0))};if(ON){const b={venue:v.v,team_a:v.a,team_b:v.b,match_date:v.d,format:v.fm,base_price:v.base,capacity:v.cap,sold:v.sold,hype:v.hype};return run(id!=null?api('/api/matches/'+id,'PUT',b):api('/api/matches','POST',b))}if(id!=null)Object.assign(m,v);else S.matches.push({id:Date.now(),...v});save()}))}
function matchDel(id){guard(()=>{if(confirm(t('confirm_delete_ticket'))){if(ON)return run(api('/api/matches/'+id,'DELETE')).then(render);S.matches=S.matches.filter(x=>x.id!=id);save();render()}})}
/* ---- admin import / export (Stumps or any CSV/JSON) ---- */
const csv=t=>{const R=[];let r=[],c='',inq=false;for(let i=0;i<t.length;i++){const ch=t[i];if(inq){if(ch=='"'&&t[i+1]=='"'){c+='"';i++}else if(ch=='"')inq=false;else c+=ch}else if(ch=='"')inq=true;else if(ch==','){r.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;r.push(c);c='';R.push(r);r=[]}else c+=ch}if(c||r.length){r.push(c);R.push(r)}return R.filter(x=>x.some(v=>v!==''))};
const IMPF=[['name','Player name'],['code','Player ID (optional, e.g. UKP0001)'],['team','Team'],['fm','Format'],['y','Year'],...SF.map(k=>[k[0],k[1]])];
const ALI={code:['playerid','id','code','uniqueid','pid'],name:['player','playername','name','batsman'],team:['team','teamname','club'],fm:['format','matchtype','type'],y:['year','season'],m:['mat','matches','matchesplayed'],i:['inns','innings','inn','battinginnings'],no:['no','notouts','notout','not_outs','not-outs'],r:['runs','runsscored'],f:['50s','fifties','50'],h:['100s','hundreds','100'],s6:['6s','sixes'],s4:['4s','fours'],hs:['highscore','highestscore'],sr:['strikerate'],w:['wkts','wickets'],bi:['bowlinginnings','bowlinns'],bb:['bbi','best','bestbowling'],w3:['3w','3wkts'],w5:['5w','5wkts'],ec:['econ','economy','er'],ba:['bowlavg','bowlingaverage','bowlingavg'],ct:['catches'],ro:['runouts'],st:['stumpings']};
function impFile(el){const f=el.files[0];if(!f)return;const fr=new FileReader();fr.onload=()=>{try{let t=String(fr.result).replace(/^\uFEFF/,''),rows,h;if(/^\s*[\[{]/.test(t)){let j=JSON.parse(t);j=Array.isArray(j)?j:(j.rows||j.data||j.players||[]);rows=j.map(o=>Object.fromEntries(Object.entries(o).map(([k,v])=>[k,v&&typeof v=='object'?JSON.stringify(v):v])));h=[...new Set(rows.flatMap(o=>Object.keys(o)))]}else{const R=csv(t);h=R[0].map(x=>x.trim());rows=R.slice(1).map(r=>Object.fromEntries(h.map((k,i)=>[k,(r[i]||'').trim()])))}
 const map={};IMPF.forEach(([k])=>{map[k]=h.find(x=>ALI[k].includes(norm(x))||norm(x)==k)||''});IMP={headers:h,rows,map,df:'T20I',name:f.name};render()}catch(e){alert('Could not read file: '+e.message)}};fr.readAsText(f)}
function applyImport(rows){const o={rows:0,players:0,teams:0};rows.forEach(v=>{let tm=v.team&&S.teams.find(x=>x.n.toLowerCase()==v.team.toLowerCase());if(!tm&&v.team){tm={id:Date.now()+o.teams++,n:v.team,logo:''};S.teams.push(tm)}let p=(v.code&&S.players.find(x=>x.code==String(v.code).toUpperCase()))||S.players.find(x=>x.n.toLowerCase()==v.name.toLowerCase());if(!p){p={id:Date.now()+1000+o.players++,code:nextCode(),n:v.name,t:tm?tm.id:S.teams[0].id,role:'Batter',dob:'',bs:'',bw:'',st:{Test:[],ODI:[],T20I:[]}};S.players.push(p)}const d={...v,tm:tm?tm.id:p.t};delete d.name;delete d.team;delete d.fm;delete d.code;const row=p.st[v.fm].find(z=>z.y==v.y&&(z.tm??p.t)==d.tm);row?Object.assign(row,d):p.st[v.fm].push(d);o.rows++});save();return o}
async function impRun(){const rows=IMP.rows.map(o=>{const g=k=>IMP.map[k]?o[IMP.map[k]]:'',f=norm(g('fm')||IMP.df),v={code:String(g('code')||'').trim(),name:String(g('name')||'').trim(),team:String(g('team')||'').trim(),fm:f.includes('test')?'Test':/odi|oneday/.test(f)?'ODI':f.includes('t20')?'T20I':null,y:Math.round(+g('y'))||new Date().getFullYear()};SF.forEach(k=>v[k[0]]=k[0]=='bb'?(g('bb')||'-'):parseFloat(g(k[0]))||0);return v}).filter(v=>v.name&&v.fm);
 if(!rows.length)return alert('No usable rows. Check the Player name and Format columns.');
 try{let res;if(ON){res=await api('/api/admin/import','POST',{rows});await load()}else res=applyImport(rows);IMP=null;render();alert(`Imported ${res.rows} rows · ${res.players} new players · ${res.teams} new teams`)}catch(e){alert(e.message)}}
