function sAdd(){const L=DRAFT[sf],y=L.length?Math.max(...L.map(r=>+r.y||0))+1:new Date().getFullYear();L.push(blankRow(y,P(DRAFTID).t));dsave();render()}
function sDel(i){DRAFT[sf].splice(i,1);dsave();render()}
async function sSave(id){const p=P(id),out={};for(const f of F){const seen=new Set();out[f]=[];for(const r of DRAFT[f]){const y=Math.round(+r.y),tm=+(r.tm??p.t);if(!(y>=1900&&y<=2100))return alert(`${f}: enter a valid year in every row`);if(seen.has(y+'|'+tm))return alert(`${f}: ${y} is entered twice for ${T(tm)?.n}`);seen.add(y+'|'+tm);const o={y,tm};SF.forEach(k=>o[k[0]]=k[0]=='bb'?(String(r.bb||'-').trim()||'-'):(parseFloat(r[k[0]])||0));out[f].push(o)}out[f].sort((a,b)=>a.y-b.y)}
 try{if(ON){await api('/api/players/'+id+'/stats','PUT',{st:out});await load()}else{p.st=out;save()}DRAFT=null;localStorage.removeItem('ukdraft');const q2=P(id);alert('Stats saved for '+(q2?.code||'')+'. Listed under: '+playerTeams(q2).map(i=>T(i)?.n).filter(Boolean).join(', '));location.hash='#/player/'+id;render()}catch(e){alert(e.message)}}
function clearStats(){guard(()=>{if(!confirm('Remove ALL player and tournament stats? This cannot be undone.'))return;if(ON)return run(api('/api/admin/stats','DELETE')).then(render);S.players.forEach(p=>p.st=gen());S.tours.forEach(t=>t.rows=[]);save();render()})}
const tmOf=(r,p)=>r.tm??p.t,playerTeams=p=>[...new Set([p.t,...F.flatMap(f=>p.st[f].map(r=>tmOf(r,p)))])],nextCode=()=>'UKP'+String((S.pc=(S.pc||0)+1)).padStart(4,'0'),SUMT=(p,f,tid)=>agg(0,raw(p,f,tid));
/* ---- news ---- */
const TAGC={News:'#00195f','Match report':'#c2185b',Announcement:'#2e7d32',Rankings:'#7b1fa2',Fans:'#ef6c00'},NTAGS=Object.keys(TAGC);
const ago=d=>{const s=(Date.now()-new Date(d))/1000;if(isNaN(s))return'';return s<3600?Math.max(1,Math.round(s/60))+' min ago':s<86400?Math.round(s/3600)+' h ago':s<2592000?Math.round(s/86400)+' days ago':new Date(d).toLocaleDateString('en-IN',{dateStyle:'medium'})};
const nbg=n=>n.img?`background:url('${esc(String(n.img).replace(/'/g,'%27'))}') center/cover`:`background:linear-gradient(135deg,${TAGC[n.tag]||'#00195f'},#1f3a9e)`;
const TAGI={News:'📰','Match report':'🏏',Announcement:'📢',Rankings:'🏆',Fans:'🎉'},rmin=b=>Math.max(1,Math.round(String(b||'').split(/\s+/).length/200));
const ncard=(n,big)=>{const c=TAGC[n.tag]||'#00195f';return`<article class="ncard card overflow-hidden ${big?'md:col-span-2 md:flex-row':''}"><a href="#/news/${n.id}" class="nimg ${big?'md:w-1/2 min-h-[200px] md:min-h-[280px]':'h-40'} shrink-0"><i style="${nbg(n)}"></i>${n.img?'':`<span class="nico">${TAGI[n.tag]||'📰'}</span>`}<span class="ntag" style="background:${c}">${esc(n.tag||'News')}</span>${n.ai?'<span class="absolute right-3 top-3 text-[10px] font-extrabold px-2 py-1 rounded-full bg-white text-[#00195f]">✦ AI VERIFIED</span>':''}</a><div class="nact"><button onclick="newsForm(${n.id})" aria-label="Edit news">✎</button><button onclick="newsDel(${n.id})" aria-label="Delete news">🗑</button></div><div class="p-5 flex flex-col gap-2 flex-1"><a href="#/news/${n.id}" class="${big?'text-2xl':'text-base'} font-extrabold leading-snug clamp3">${esc(n.t)}</a>${big&&n.body?`<p class="text-sm clamp3" style="color:var(--mut)">${esc(n.body)}</p>`:''}<div class="flex items-center justify-between text-xs mt-auto pt-3" style="color:var(--mut)"><span>${ago(n.d)}${n.body?' · '+rmin(n.body)+' min read':''}</span><a href="#/news/${n.id}" class="font-bold" style="color:${c}">Read →</a></div></div></article>`};
const newsSorted=()=>[...S.news].sort((a,b)=>String(b.d).localeCompare(String(a.d)));
const newsBlock=n=>`<div class="flex justify-between items-center mb-3 gap-3"><h2 class="text-xl font-extrabold">Latest news</h2><div class="flex gap-2"><button class="btn" onclick="newsForm()">+ Add news</button><a class="btn o" href="#/news">View all</a></div></div><div class="grid md:grid-cols-3 gap-4">${newsSorted().slice(0,n).map((x,i)=>ncard(x,i==0)).join('')||'<p>No news yet.</p>'}</div>`;
const nlist=()=>{const L=newsSorted().filter(x=>(!ntag||x.tag==ntag)&&(!nq||(x.t+' '+(x.body||'')).toLowerCase().includes(nq.toLowerCase())));return `<div class="smart-news-panel card p-4 mb-5"><div class="flex items-center justify-between gap-3"><div><b>Smart newsroom intelligence</b><div class="text-xs mt-1" style="color:var(--mut)">Stories are ranked by recency, match activity and fan interest. Refreshes automatically.</div></div><span class="smart-live-pill">● LIVE</span></div></div>`+(L.map((x,i)=>ncard(x,i==0&&!nq&&!ntag)).join('')||'<p class="text-sm">No news found.</p>');};
const seedNews=()=>[['Kozhikode announce squad for the new season','Announcement'],['Rankings updated after latest fixtures','Rankings'],['Wayanad crowned Malabar Cup 2026 champions after thrilling victory over Kozhikode','Match report'],['Fixtures for Champions Trophy 2026 released','Announcement'],['Aathif Khan crowned No.1 T20 Player in 2025–26 Rankings','Rankings'],['KCA ANNOUNCES GRADE-WISE PLAYER SALARY STRUCTURE FOR KERALA SUPER LEAGUE 2027','Announcement'],['KCA Inter-Zone U-23 competition underway','News'],['70,000+ fans: Old Stafford Stadium sets historic attendance record is still unbeatable','Fans'],['Kerala discuss new captain for Ranji Trophy 2026–27','News']].map((x,i)=>({id:500+i,t:x[0],tag:x[1],img:'',body:'',d:new Date(Date.now()-i*252e5).toISOString()}));
async function aiNewsRefresh(b){guard(async()=>{if(!ON)return alert('Start the backend first.');if(role()!='admin')return alert('Admin access required.');b?.setAttribute('disabled','disabled');if(b)b.textContent='Generating…';try{await api('/api/ai/news','POST',{});await load();render();}catch(e){alert(e.message)}finally{if(b){b.removeAttribute('disabled');b.textContent='✦ Refresh AI news'}}})}
function newsForm(id){const x=id!=null?S.news.find(z=>z.id==id):{t:'',tag:'News',img:'',body:''};guard(()=>form(id!=null?'Edit news':'Add news',[['Headline','t',x.t],['Category','tag',x.tag,NTAGS.map(k=>[k,k])],['Image (upload or paste a link)','img',x.img||'','img'],['Story','body',x.body||'','area']],d=>{if(!d.t.trim())throw new Error('Enter a headline');const b={title:d.t.trim(),tag:d.tag,img:d.img||null,body:d.body.trim()||null};if(ON)return run(id!=null?api('/api/news/'+id,'PUT',b):api('/api/news','POST',b));if(id!=null)Object.assign(x,{t:b.title,tag:b.tag,img:d.img||'',body:b.body||''});else S.news.push({id:Date.now(),t:b.title,tag:b.tag,img:d.img||'',body:b.body||'',d:new Date().toISOString()});save()}))}
function newsDel(id){guard(()=>{if(!confirm('Delete this news item?'))return;if(ON)return run(api('/api/news/'+id,'DELETE')).then(()=>{location.hash='#/news';render()});S.news=S.news.filter(z=>z.id!=id);save();location.hash='#/news';render()})}
/* ---- ticket list filters ---- */
let tq='',tteam='';
const matchDT=m=>new Date(String(m.d||'').replace(' ','T'));
const matchPast=m=>{const d=matchDT(m);return !isNaN(d.getTime())&&d.getTime()<Date.now()};
const smartHype=m=>{const d=matchDT(m),days=Math.max(0,(d-Date.now())/864e5),fill=m.cap?m.sold/m.cap:0,urgency=days<1?18:days<3?12:days<7?7:2;return Math.max(0,Math.min(99,Math.round((+m.hype||0)+fill*18+urgency)))};
const smartDemand=m=>{const h=smartHype(m);return h>=82?'Very high':h>=65?'High':h>=45?'Medium':'Normal'};
const tmatch=m=>!matchPast(m)&&(!tv||m.v==tv)&&(!tteam||m.a==tteam||m.b==tteam)&&(!tq||`${T(m.a)?.n} ${T(m.b)?.n} ${m.v} ${m.fm}`.toLowerCase().includes(tq.toLowerCase()));
const tcard=(m,history=false)=>{const pc=Math.round(m.sold/m.cap*100),full=m.sold>=m.cap,h=smartHype(m),d=smartDemand(m);return `<div class="card p-5 ${history?'ticket-history-card':''}"><div class="flex justify-between text-xs font-bold" style="color:var(--mut)"><span>${fdate(m.d)}</span><span>${m.fm}</span></div><div class="text-xl font-extrabold my-2">${esc(T(m.a)?.n||'?')} vs ${esc(T(m.b)?.n||'?')}</div><div class="text-sm mb-3">📍 ${esc(m.v)}</div>${history?`<div class="ticket-past-badge">PAST MATCH · HISTORY</div><div class="text-xs mt-2" style="color:var(--mut)">This fixture has moved automatically to ticket history.</div>`:`<div class="flex items-center justify-between gap-2 text-xs font-bold mb-1"><span>SMART DEMAND · ${d.toUpperCase()}</span><span>${h}%</span></div><div class="h-2 rounded-full mb-3" style="background:var(--line)"><div class="h-2 rounded-full" style="width:${h}%;background:#ff1fe0"></div></div><div class="text-xs mb-3" style="color:var(--mut)">${pc}% ${t('sold')} · ${m.cap-m.sold} ${t('seats_left')} · ${h>=70?'🔥 Selling fast':''}</div><div class="flex items-center justify-between"><div><div class="text-xs" style="color:var(--mut)">${t('general_from')}</div><div class="text-2xl font-extrabold">₹${tprice({...m,hype:h},'General')}</div></div><button class="btn" onclick="book(${m.id})" ${full?'disabled':''}>${full?t('sold_out'):t('book').toUpperCase()}</button></div>`}</div>`};
const tlist=()=>S.matches.filter(tmatch).sort((a,b)=>matchDT(a)-matchDT(b)).map(m=>tcard(m)).join('')||'<p>No upcoming matches found.</p>';
const thistory=()=>S.matches.filter(m=>matchPast(m)&&(!tv||m.v==tv)&&(!tteam||m.a==tteam||m.b==tteam)&&(!tq||`${T(m.a)?.n} ${T(m.b)?.n} ${m.v} ${m.fm}`.toLowerCase().includes(tq.toLowerCase()))).sort((a,b)=>matchDT(b)-matchDT(a)).slice(0,12).map(m=>tcard(m,true)).join('');
const blist=()=>(S.bookings||[]).slice().reverse().filter(b=>{const m=S.matches.find(x=>x.id==b.mid);return!m||tmatch(m)}).map(b=>{const m=S.matches.find(x=>x.id==b.mid);return`<div class="card p-4 mb-2 flex justify-between gap-3 text-sm"><div><b>UK-${Number(b.id).toString(36).toUpperCase()}</b> · ${m?`${esc(T(m.a)?.n||'?')} vs ${esc(T(m.b)?.n||'?')}, ${esc(m.v)}`:'Match'}<div class="text-xs" style="color:var(--mut)">${b.qty} × ${b.cat}</div></div><b>₹${b.amount}</b></div>`}).join('')||'<p class="text-sm">No bookings yet.</p>';
const bref=b=>'UK-'+Number(b.id).toString(36).toUpperCase();
const bcards=()=>(S.bookings||[]).slice().reverse().filter(b=>{const m=S.matches.find(x=>x.id==b.mid);if(bteam&&!(m&&(m.a==bteam||m.b==bteam)))return false;if(bcat&&b.cat!=bcat)return false;return!bq||`${bref(b)} ${b.cat} ${m?`${T(m.a)?.n} ${T(m.b)?.n} ${m.v} ${m.fm}`:''}`.toLowerCase().includes(bq.toLowerCase())}).map(b=>{const m=S.matches.find(x=>x.id==b.mid),A=m&&T(m.a),B=m&&T(m.b);return`<div class="card p-4 mb-3 flex items-center gap-4"><div class="flex -space-x-2 shrink-0">${A?tav(A,'w-10 h-10'):''}${B?tav(B,'w-10 h-10'):''}</div><div class="min-w-0 flex-1"><div class="font-extrabold truncate">${m?`${esc(A?.n||'?')} vs ${esc(B?.n||'?')}`:'Match'}</div><div class="text-xs" style="color:var(--mut)">${m?`${esc(m.v)} · ${fdate(m.d)}`:''}</div><div class="text-xs mt-1"><b>${bref(b)}</b> · ${b.qty} × ${b.cat}</div></div><b class="shrink-0">₹${b.amount}</b></div>`}).join('')||'<div class="card p-8 text-center text-sm">No bookings found.</div>';
/* ---------- tournaments ---------- */
const TT=id=>S.tours.find(t=>t.id==id);let ttab='ins',tt='bat',spm=false;
const tcards=(n=99)=>sortedTours().slice(0,n).map(x=>`<a href="#/tour/${x.id}"><div class="tour">${x.y}</div><div class="font-extrabold text-sm mt-2">${x.n}</div></a>`).join('')||'<p>No tournaments yet.</p>';
const seedTours=()=>[['Kerala Premier League T20',2026,'T20I'],['Malabar Cup',2026,'ODI'],['Travancore Trophy',2025,'ODI'],['Freedom Trophy T20',2025,'T20I']].map((x,i)=>{const t={id:200+i,n:x[0],y:x[1],fm:x[2]};t.rows=[];return t});
const TIERS=[['broadcaster',''],['bpartner','BROADCAST PARTNERS'],['premier','PREMIER PARTNERS'],['global','GLOBAL PARTNERS'],['supporter','OFFICIAL SUPPORTERS']];
const seedSpon=()=>[['Broadcaster One','broadcaster','#0a1f5c'],['Broadcaster Two','broadcaster','#c2185b'],['Partner One','bpartner','#1a1a1a'],['Partner Two','bpartner','#b71c1c'],['Partner Three','bpartner','#4a90d9'],['Premier One','premier','#c62828'],['Premier Two','premier','#2e9b48'],['Premier Three','premier','#1c2f6b'],['Global One','global','#b71c1c'],['Global Two','global','#d4a017'],['Global Three','global','#1f6f6b'],['Supporter One','supporter','#7a1c1c'],['Supporter Two','supporter','#1f3f8f']].map((x,i)=>({id:300+i,n:x[0],tier:x[1],color:x[2]}));
const ink=c=>{const n=parseInt(c.slice(1),16);return(((n>>16)*299+((n>>8&255)*587)+(n&255)*114)/1000)>150?'#00195f':'#fff'};
const topN=(a,k,n=5,asc)=>[...a].sort((x,y)=>asc?x[k]-y[k]:y[k]-x[k]).slice(0,n);
const trow=(x,v)=>`<a href="#/player/${x.p.id}" class="flex items-center gap-3 py-2 border-b" style="border-color:var(--line)"><div class="av w-9 h-9 text-xs">${ini(x.p.n)}</div><div class="flex-1 text-sm font-bold">${x.p.n}<div class="text-xs font-medium" style="color:var(--mut)">${T(x.p.t).n}</div></div><div class="font-extrabold">${v}</div></a>`;
const lb=(title,a,k,f=x=>x[k],asc)=>`<div class="card p-5"><div class="font-extrabold mb-2">${title}</div>${topN(a,k,5,asc).map(x=>trow(x,f(x))).join('')||'<p class="text-sm">No data</p>'}</div>`;
const PT={bat:s=>Math.round(s.r/4+(s.i?s.r/s.i:0)*2+s.h*10+s.f*3),bowl:s=>Math.max(0,Math.round(s.w*6+s.w5*25+s.w3*10-(s.w?s.ec:0)*2)),all:s=>PT.bat(s)+PT.bowl(s)},ptf=(p,f,c)=>{const s=sum(p,f);return c=='all'&&!(s.r>0&&s.w>0)?0:PT[c](s)};
const csum=p=>`<div class="text-3xl font-extrabold mb-2">${t('career_summary').toUpperCase()}</div><div class="card overflow-x-auto mb-6"><table class="w-full career-summary-table"><thead><tr>${[pi('format'),pi('mat'),pi('inn'),pi('runs'),t('not_outs'),pi('avg'),pi('sr'),pi('hs'),pi('hundreds'),pi('fifties'),pi('wkts'),pi('best'),pi('econ'),pi('catches')].map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${['Overall',...F].map(f=>{const s=sum(p,f);return`<tr><td>${f.toUpperCase()}</td><td>${s.m}</td><td>${s.i}</td><td>${s.r}</td><td>${s.no}</td><td>${av(s)}</td><td>${s.sr}</td><td>${s.hs}</td><td>${s.h}</td><td>${s.f}</td><td>${s.w}</td><td>${s.bb}</td><td>${s.w?s.ec:'-'}</td><td>${s.ct}</td></tr>`}).join('')}</tbody></table></div>`;
const ttable=(tid,list,kind)=>`<div class="card overflow-x-auto mt-4"><table class="w-full"><thead><tr><th style="text-align:left;padding-left:16px">PLAYER</th>${TH[kind].map(h=>`<th>${h}</th>`).join('')}<th></th></tr></thead><tbody>${topN(list,SK[kind],40).map(x=>`<tr><td style="text-align:left;padding-left:16px"><a href="#/player/${x.p.id}">${x.p.n}</a></td>${TC[kind](x).map(v=>`<td>${v}</td>`).join('')}<td class="whitespace-nowrap"><button class="text-xs font-bold mr-2" onclick="tStat(${tid},${x.p.id})">${t('edit')}</button><button class="text-xs font-bold" onclick="tDel(${tid},${x.p.id})">✕</button></td></tr>`).join('')||'<tr><td colspan="12">No stats yet. Use Add stats.</td></tr>'}</tbody></table></div>`;

/* ---------- tournament champions / runners ---------- */
const championForm=(id,tourId)=>{
 const old=id!=null?(S.champions||[]).find(x=>x.id==id):null;
 const x=old||{tournament_id:tourId||S.tours[0]?.id||'',year:new Date().getFullYear(),winner_team_id:S.teams[0]?.id||'',runner_team_id:'',trophy:'',img:'',note:''};
 guard(()=>form(id!=null?'Edit champion record':'Add champion record',[
  ['Tournament','tournament_id',x.tournament_id,S.tours.map(z=>[z.id,z.n+' · '+z.y])],
  ['Year','year',x.year],
  ['Champion / winner','winner_team_id',x.winner_team_id,teamOpts()],
  ['Runner-up','runner_team_id',x.runner_team_id??'', [['','— none —'],...teamOpts()]],
  ['Trophy name','trophy',x.trophy||''],
  ['Trophy / celebration image','img',x.img||'','img'],
  ['Notes','note',x.note||'','area']
 ],d=>{
   const year=Math.round(+d.year);
   if(!d.tournament_id||!d.winner_team_id)throw new Error('Choose tournament and champion');
   if(!(year>=1900&&year<=2100))throw new Error('Enter a valid year');
   const b={tournament_id:+d.tournament_id,year,winner_team_id:+d.winner_team_id,runner_team_id:d.runner_team_id===''?null:+d.runner_team_id,trophy:d.trophy.trim(),img:d.img||'',note:d.note.trim()};
   if(ON)return run(api(id!=null?'/api/champions/'+id:'/api/champions',id!=null?'PUT':'POST',b));
   if(id!=null)Object.assign(old,b);else(S.champions||(S.champions=[])).push({id:Date.now(),...b});
   save();render();
 }));
};
function championDel(id){guard(()=>{if(!confirm('Delete this champions record?'))return;if(ON)return run(api('/api/champions/'+id,'DELETE'));S.champions=(S.champions||[]).filter(x=>x.id!=id);save();render()})}
function tournamentChampionsView(tid){
 const C=[...(S.champions||[])].filter(c=>c.tournament_id==tid).map(c=>({...c,win:T(c.winner_team_id),run:T(c.runner_team_id)})).filter(c=>c.win).sort((a,b)=>b.year-a.year||b.id-a.id);
 return `<div class="flex flex-wrap justify-between items-center gap-3 mb-5"><div><h2 class="text-2xl font-extrabold">CHAMPIONS</h2><p class="text-sm mt-1" style="color:var(--mut)">Champions and runners-up for this tournament.</p></div><button class="btn" onclick="championForm(null,${tid})">+ Add champion</button></div>${C.map(c=>`<div class="card p-4 md:p-5 mb-4"><div class="grid md:grid-cols-[80px_1fr_auto] gap-4 items-center"><div class="text-4xl text-center">🏆</div><div><div class="text-xs font-extrabold" style="color:#e0149b">${c.year}</div><div class="flex flex-wrap gap-3 items-center mt-1"><div><span class="text-[10px] font-extrabold" style="color:var(--mut)">CHAMPION</span><a class="block text-lg font-extrabold" href="#/team/${c.win.id}">${esc(c.win.n)}</a></div><div class="text-xl opacity-40">vs</div><div><span class="text-[10px] font-extrabold" style="color:var(--mut)">RUNNER-UP</span><div class="text-lg font-extrabold">${c.run?`<a href="#/team/${c.run.id}">${esc(c.run.n)}</a>`:'—'}</div></div></div>${c.trophy?`<div class="text-xs mt-2" style="color:var(--mut)">🏆 ${esc(c.trophy)}</div>`:''}${c.note?`<div class="text-xs mt-1" style="color:var(--mut)">${esc(c.note)}</div>`:''}</div><div class="flex md:flex-col gap-2"><button class="av w-8 h-8 text-xs" onclick="championForm(${c.id})">✎</button><button class="av w-8 h-8 text-xs" onclick="championDel(${c.id})">✕</button></div></div>${c.img?`<img src="${esc(c.img)}" class="mt-4 w-full h-36 object-cover rounded-xl" alt="">`:''}</div>`).join('')||'<div class="card p-8 text-center" style="color:var(--mut)">No champion records for this tournament yet.</div>'}`;
}

function championsView(){
 const C=[...(S.champions||[])].map(c=>({...c,tour:S.tours.find(t=>t.id==c.tournament_id),win:T(c.winner_team_id),run:T(c.runner_team_id)})).filter(c=>c.tour&&c.win);
 C.sort((a,b)=>b.year-a.year||String(a.tour.n).localeCompare(String(b.tour.n)));
 const years=[...new Set(C.map(c=>c.year))];
 return `<div class="flex flex-wrap justify-between items-center gap-3 mb-5"><div><h2 class="text-2xl md:text-3xl font-extrabold">CHAMPIONS</h2><p class="text-sm mt-1" style="color:var(--mut)">Winners and runners-up, arranged year by year.</p></div><button class="btn" onclick="championForm()">+ Add champion</button></div>
 ${years.map(y=>`<section class="mb-7"><div class="flex items-center gap-3 mb-3"><div class="text-3xl font-extrabold">${y}</div><div class="h-px flex-1" style="background:var(--line)"></div></div><div class="space-y-3">${C.filter(c=>c.year==y).map(c=>`<div class="card p-4 md:p-5"><div class="grid md:grid-cols-[90px_1fr_1fr_auto] gap-4 items-center"><div class="text-4xl text-center">🏆</div><div><div class="text-xs font-extrabold" style="color:#e0149b">${esc(c.tour.n)}</div><div class="text-xs mt-1" style="color:var(--mut)">${esc(c.tour.fm||'')}</div></div><div><div class="flex flex-wrap gap-3 items-center"><div><span class="text-[10px] font-extrabold" style="color:var(--mut)">CHAMPION</span><a class="block text-lg font-extrabold" href="#/team/${c.win.id}">${esc(c.win.n)}</a></div><div class="text-xl opacity-40">vs</div><div><span class="text-[10px] font-extrabold" style="color:var(--mut)">RUNNER-UP</span><div class="text-lg font-extrabold">${c.run?`<a href="#/team/${c.run.id}">${esc(c.run.n)}</a>`:'—'}</div></div></div>${c.trophy?`<div class="text-xs mt-2" style="color:var(--mut)">🏆 ${esc(c.trophy)}</div>`:''}${c.note?`<div class="text-xs mt-1" style="color:var(--mut)">${esc(c.note)}</div>`:''}</div><div class="flex md:flex-col gap-2 justify-end"><button class="av w-8 h-8 text-xs" onclick="championForm(${c.id})" aria-label="Edit">✎</button><button class="av w-8 h-8 text-xs" onclick="championDel(${c.id})" aria-label="Delete">✕</button></div></div>${c.img?`<img src="${esc(c.img)}" class="mt-4 w-full h-36 object-cover rounded-xl" alt="">`:''}</div>`).join('')||'<div class="card p-8 text-center" style="color:var(--mut)">No champion records yet. Use Add champion to create the first year.</div>'}</div></section>`).join('')}`;
}

function tourForm(id){const t0=id!=null?TT(id):{n:'',y:2026,fm:'T20I'};guard(()=>form(id!=null?'Edit tournament':'Add tournament',[['Name','n',t0.n],['Year','y',t0.y],['Format','fm',t0.fm,F.map(f=>[f,f])]],d=>{if(!d.n.trim())return;const b={name:d.n.trim(),year:+d.y,format:d.fm};if(ON)return run(id!=null?api('/api/tournaments/'+id,'PUT',b):api('/api/tournaments','POST',b));if(id!=null)Object.assign(t0,{n:b.name,y:b.year,fm:b.format});else S.tours.push({id:Date.now(),n:b.name,y:b.year,fm:b.format,rows:[]});save()}))}
function tourDel(id){guard(()=>{if(confirm('Delete this tournament and all its stats?')){if(ON)return run(api('/api/tournaments/'+id,'DELETE')).then(()=>{location.hash='#/tournaments';render()});S.tours=S.tours.filter(t=>t.id!=id);save();location.hash='#/tournaments'}})}
function tStat(tid,pid){const tr=TT(tid),old=(pid!=null&&tr.rows.find(x=>x.p==pid))||{};guard(()=>form((pid!=null?'Edit':'Add')+' tournament stats',[['Player','p',pid??'',S.players.map(p=>[p.id,(p.code||'')+' · '+p.n+' ('+(T(p.t)?.n||'')+')'])],...SF.map(k=>[k[1],k[0],old[k[0]]??(k[0]=='bb'?'-':0)])],d=>{const v={p:+d.p};SF.forEach(k=>v[k[0]]=k[0]=='bb'?(d.bb||'-'):+d[k[0]]||0);if(ON)return run(api('/api/tstats','POST',{tour_id:tid,player_id:v.p,...v}));const i=tr.rows.findIndex(x=>x.p==v.p);i>=0?tr.rows[i]=v:tr.rows.push(v);save()}))}
function tDel(tid,pid){guard(()=>{if(confirm('Remove this player from the tournament stats?')){if(ON)return run(api('/api/tstats/'+tid+'/'+pid,'DELETE')).then(render);const tr=TT(tid);tr.rows=tr.rows.filter(x=>x.p!=pid);save();render()}})}
function spForm(id){const x=id!=null?S.sponsors.find(z=>z.id==id):{n:'',tier:'premier',color:'#00195f'};guard(()=>form(id!=null?'Edit sponsor':'Add sponsor',[['Name','n',x.n],['Category','tier',x.tier,TIERS.map(z=>[z[0],z[1]||'BROADCASTERS'])],['Colour (hex, e.g. #c62828)','color',x.color]],d=>{if(!d.n.trim())return;const c=/^#[0-9a-f]{6}$/i.test(d.color)?d.color:'#00195f',b={name:d.n.trim(),tier:d.tier,color:c};if(ON)return run(id!=null?api('/api/sponsors/'+id,'PUT',b):api('/api/sponsors','POST',b));if(id!=null)Object.assign(x,{n:b.name,tier:b.tier,color:c});else S.sponsors.push({id:Date.now(),n:b.name,tier:b.tier,color:c});save()}))}
function spDel(id){guard(()=>{if(confirm('Remove this sponsor?')){if(ON)return run(api('/api/sponsors/'+id,'DELETE')).then(render);S.sponsors=S.sponsors.filter(z=>z.id!=id);save();render()}})}
let pq='',pteam='',nq='',ntag='',bq='',bteam='',bcat='';
let statFmt='Overall',statTeam='',statMetric='r';
const plist=()=>sortedPlayers().filter(p=>(!pteam||playerTeams(p).includes(+pteam))&&(!pq||(p.n+' '+(p.code||'')+' '+(T(p.t)?.n||'')).toLowerCase().includes(pq.toLowerCase()))).map(pcard).join('')||'<p class="text-sm">No players found.</p>';
function goStats(){const v=($('#gsid').value||'').trim().toLowerCase();if(!v)return;const p=S.players.find(x=>String(x.code||'').toLowerCase()==v)||S.players.find(x=>x.n.toLowerCase()==v);if(!p)return alert('No player with this ID. Check the Player ID on the profile (like UKP0001).');statsEdit(p.id)}
async function shareCurrent(kind,id){const url=location.href;const title=kind==='team'?(T(id)?.n||'Team profile'):(P(id)?.n||'Player profile');const text=`${title} — United Keralam`;try{if(navigator.share){await navigator.share({title,text,url});return}}catch(e){if(e?.name==='AbortError')return}try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(url);alert(t('link_copied'));return}}catch(e){}try{const ta=document.createElement('textarea');ta.value=url;ta.setAttribute('readonly','');ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove();alert(t('link_copied'));return}catch(e){}prompt('Copy profile link',url)}

function venueOf(v){return (S.venues||[]).find(x=>x.id==v || norm(x.n)===norm(v));}
function venueName(v){return venueOf(v)?.n||v||'-';}
function venueForm(id){const old=id!=null?(S.venues||[]).find(x=>x.id==id):null;const x=old||{n:'',location:'',home_team_id:S.teams[0]?.id||0,capacity:10000,established_year:new Date().getFullYear(),rating:7.5,reviews:1000};guard(()=>form(id!=null?t('edit_venue'):t('add_venue'),[[t('venue_name'),'n',x.n],[t('location'),'location',x.location],[t('home_team'),'home_team_id',x.home_team_id,teamOpts()],[t('capacity'),'capacity',x.capacity],[t('established_year'),'established_year',x.established_year],['Fan rating (0–10)','rating',x.rating],['Fan reviews count','reviews',x.reviews]],async d=>{const b={name:d.n.trim(),location:d.location.trim(),home_team_id:+d.home_team_id,capacity:Math.max(1,Math.round(+d.capacity||1)),established_year:Math.max(1800,Math.round(+d.established_year||new Date().getFullYear())),rating:Math.min(10,Math.max(0,Math.round((+d.rating||0)*10)/10)),reviews:Math.max(0,Math.round(+d.reviews||0))};if(!b.name)throw new Error(t('venue_name'));if(ON)return run(api(id!=null?'/api/venues/'+id:'/api/venues',id!=null?'PUT':'POST',b));if(id!=null)Object.assign(x,{id:x.id,n:b.name,location:b.location,home_team_id:b.home_team_id,capacity:b.capacity,established_year:b.established_year,rating:b.rating,reviews:b.reviews});else(S.venues||(S.venues=[])).push({id:Date.now(),n:b.name,...b});save()}))}
function venueDel(id){guard(()=>{if(!confirm(t('confirm_delete_venue')))return;if(ON)return run(api('/api/venues/'+id,'DELETE')).then(render);S.venues=(S.venues||[]).filter(x=>x.id!=id);save();render()})}
function venueView(id){
 const v=venueOf(id); if(!v)return'';
 const ht=T(v.home_team_id), rows=(S.matches||[]).filter(m=>norm(m.v||'')===norm(v.n)||norm(m.v||'').includes(norm(v.n))||norm(v.n).includes(norm(m.v||''))).sort((a,b)=>String(a.d).localeCompare(String(b.d)));
 const vr=Number(v.rating)>0?Math.min(10,Math.max(0,Number(v.rating))):7.5, reviews=Number(v.reviews)||0;
 const compact=n=>n>=1000000?(n/1000000).toFixed(1).replace('.0','')+'M':n>=1000?(n/1000).toFixed(1).replace('.0','')+'k':String(n);
 const matchRows=rows.map(m=>{const A=T(m.a),B=T(m.b),past=String(m.d).slice(0,10)<todayS(),sold=Number(m.sold)||0,cap=Number(m.cap)||0;return `<tr><td style="text-align:left"><b>${esc(A?.n||'?')} vs ${esc(B?.n||'?')}</b><div class="text-xs" style="color:var(--mut)">${esc(m.v||v.n)}</div></td><td>${esc(fdate(m.d))}</td><td>${esc(m.fm||'T20I')}</td><td><span class="${past?'ticket-past-badge':'smart-live-pill'}">${past?'HISTORY':'UPCOMING'}</span></td><td>${sold.toLocaleString()} / ${cap.toLocaleString()}</td>${EDIT?`<td><div class="flex justify-center gap-2"><button class="btn o !py-2 !px-3" onclick="matchForm(${m.id})">${t('edit')}</button><button class="btn o !py-2 !px-3" onclick="matchDel(${m.id})">${t('del')}</button></div></td>`:''}</tr>`}).join('');
 return `<section class="hero p-7 md:p-10 mb-6"><div class="flex flex-wrap justify-between gap-4"><div><div class="text-xs font-extrabold opacity-70">${t('venue_profile').toUpperCase()}</div><h1 class="text-3xl md:text-5xl font-extrabold mt-2">${esc(v.n)}</h1><p class="mt-2 opacity-80">${esc(v.location||'-')}</p></div><div class="text-right"><div class="venue-rating text-sm inline-flex">★ ${vr.toFixed(1)}/10 (${compact(reviews)} reviews)</div>${ht?`<a class="btn !bg-white !text-[#00195f] mt-2" href="#/team/${ht.id}">${esc(ht.n)} →</a>`:''}</div></div></section><div class="grid grid-cols-2 md:grid-cols-5 gap-3 mb-6"><div class="card p-5"><div class="text-xs font-bold" style="color:var(--mut)">${t('location')}</div><div class="font-extrabold mt-1">${esc(v.location||'-')}</div></div><div class="card p-5"><div class="text-xs font-bold" style="color:var(--mut)">${t('home_team')}</div><div class="font-extrabold mt-1">${esc(ht?.n||'-')}</div></div><div class="card p-5"><div class="text-xs font-bold" style="color:var(--mut)">${t('capacity')}</div><div class="font-extrabold mt-1">${Number(v.capacity||0).toLocaleString()}</div></div><div class="card p-5"><div class="text-xs font-bold" style="color:var(--mut)">${t('established_year')}</div><div class="font-extrabold mt-1">${esc(v.established_year||'-')}</div></div><div class="card p-5"><div class="text-xs font-bold" style="color:var(--mut)">Matches</div><div class="font-extrabold mt-1">${rows.length}</div></div></div><div class="flex flex-wrap justify-between items-center gap-3 mb-3"><div><h2 class="text-2xl font-extrabold">${t('matches')} — ${esc(v.n)}</h2><p class="text-sm" style="color:var(--mut)">Add, edit or delete matches for this venue.</p></div>${EDIT?`<button class="btn" onclick="matchForm(null,${JSON.stringify(v.n)})">+ Add match</button>`:''}</div><div class="card overflow-x-auto"><table class="w-full min-w-[900px]"><thead><tr><th style="text-align:left">Match</th><th>Date</th><th>Format</th><th>Status</th><th>Tickets</th>${EDIT?'<th>Actions</th>':''}</tr></thead><tbody>${matchRows||`<tr><td colspan="${EDIT?6:5}" class="p-8 text-center" style="color:var(--mut)">No matches at this venue yet.</td></tr>`}</tbody></table></div>`}


/* ---------- statistics leaders ---------- */
const STAT_METRICS=[['r','most_runs','Runs'],['w','most_wickets','Wickets'],['m','most_matches','Matches'],['h','most_100s','100s'],['f','most_50s','50s'],['s4','most_fours','4s'],['s6','most_sixes','6s'],['w3','most_3w','3W'],['w5','most_5w','5W'],['hs','highest_score','Highest score'],['sr','best_strike_rate','Best strike rate'],['ct','most_catches','Catches'],['ro','most_runouts','Run-outs'],['st','most_stumpings','Stumpings']];
const statMetricLabel=k=>{const x=STAT_METRICS.find(z=>z[0]==k);return x?t(x[1]):k};
function statRowsFor(p,fmt,tid){if(fmt==='Overall')return F.flatMap(f=>p.st[f].filter(r=>tid===''||(r.tm??p.t)==+tid));return p.st[fmt].filter(r=>tid===''||(r.tm??p.t)==+tid)}
function statValue(p,fmt,tid,key){const a=statRowsFor(p,fmt,tid);if(key==='hs')return Math.max(0,...a.map(r=>+r.hs||0));if(key==='sr')return a.length?Math.max(0,...a.map(r=>+r.sr||0)):0;return a.reduce((n,r)=>n+(+r[key]||0),0)}
function statLeaderboard(){const rows=S.players.map(p=>({p,v:statValue(p,statFmt,statTeam,statMetric)})).filter(x=>x.v>0);rows.sort((a,b)=>b.v-a.v||byName(a.p,b.p));return rows}
function statProfileModal(p,position,value){const rows=statRowsFor(p,statFmt,statTeam),teamIds=[...new Set(rows.map(r=>r.tm??p.t))].map(id=>T(id)).filter(Boolean),statCards=[['m','Matches'],['r','Runs'],['w','Wickets'],['h','100s'],['f','50s'],['s4','4s'],['s6','6s'],['w3','3W'],['w5','5W'],['hs','HS'],['sr','SR'],['ct','Catches'],['ro','Run-outs'],['st','Stumpings']],img=p.photo?`<img src="${esc(p.photo)}" class="w-16 h-16 rounded-full object-cover" alt="">`:`<div class="av w-16 h-16 text-xl">${ini(p.n)}</div>`;modal(`<div class="flex items-center gap-4 mb-5">${img}<div class="min-w-0"><div class="text-xs font-extrabold" style="color:var(--mut)">${t('player_profile').toUpperCase()}</div><h3 class="text-2xl font-extrabold truncate">${esc(p.n)}</h3><div class="text-xs font-bold mt-1" style="color:var(--mut)">${esc(p.code||'')} · ${esc(p.role||'-')} · ${esc(p.playing_role||'-')}</div></div></div><div class="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-4"><div class="card p-3"><div class="text-[10px] font-bold" style="color:var(--mut)">${t('position')}</div><div class="text-xl font-extrabold mt-1">#${position}</div></div><div class="card p-3"><div class="text-[10px] font-bold" style="color:var(--mut)">${t('selected_stat')}</div><div class="text-xl font-extrabold mt-1">${value}</div><div class="text-xs" style="color:var(--mut)">${statMetricLabel(statMetric)}</div></div><div class="card p-3"><div class="text-[10px] font-bold" style="color:var(--mut)">${t('format')}</div><div class="font-extrabold mt-1">${statFmt==='T20I'?'T20':esc(statFmt)}</div></div><div class="card p-3"><div class="text-[10px] font-bold" style="color:var(--mut)">${t('teams')}</div><div class="font-extrabold mt-1">${teamIds.length?teamIds.map(x=>esc(x.n)).join(', '):esc(T(p.t)?.n||'-')}</div></div></div><div class="grid grid-cols-3 sm:grid-cols-5 gap-2">${statCards.map(([k,l])=>`<div class="card p-3"><div class="text-[10px] font-bold" style="color:var(--mut)">${l}</div><div class="font-extrabold mt-1">${statValue(p,statFmt,statTeam,k)}</div></div>`).join('')}</div><div class="mt-5 flex gap-2"><a class="btn flex-1 text-center" href="#/player/${p.id}" onclick="closeM()">Open player profile</a><button class="btn o" onclick="closeM()">Close</button></div>`, 'max-w-2xl')}
function statisticsView(){
 const L=statLeaderboard(),show=L.slice(0,100),teams=sortedTeams();
 const fmtBtns=[['Overall',t('all_formats')],['Test',t('format_test')],['ODI',t('format_odi')],['T20I',t('format_t20')]];
 const metricCards=STAT_METRICS.map(([k,tk])=>{
   const active=statMetric===k;
   return `<button class="card uk-stat-card p-3 ${active?'active':''}" onclick="statMetric='${k}';render()">
     <div class="uk-stat-card-title text-[12px] font-extrabold" style="color:var(--mut)">${t(tk)}</div>
     <div class="text-sm font-extrabold mt-1">${t(tk)}</div>
   </button>`;
 }).join('');
 const playerRows=show.map((x,i)=>`<tr class="cursor-pointer" onclick="statProfileModal(P(${x.p.id}),${i+1},${x.v})">
   <td class="font-extrabold">${i+1}</td>
   <td style="text-align:left"><div class="flex items-center gap-3">
     ${x.p.photo?`<img src="${esc(x.p.photo)}" class="w-9 h-9 rounded-full object-cover shrink-0" alt="">`:`<span class="av w-9 h-9 text-xs shrink-0">${ini(x.p.n)}</span>`}
     <span><span class="font-extrabold block">${esc(x.p.n)}</span><span class="text-[10px]" style="color:var(--mut)">${esc(x.p.code||'')}</span></span>
   </div></td>
   <td>${esc(T(x.p.t)?.n||'-')}</td>
   <td>${esc(x.p.playing_role||x.p.role||'-')}</td>
   <td class="text-lg font-extrabold">${x.v}</td>
   <td><button class="btn o !px-3 !py-1.5 text-xs" onclick="event.stopPropagation();statProfileModal(P(${x.p.id}),${i+1},${x.v})">${t('view')||'VIEW'}</button></td>
 </tr>`).join('');
 const mobileRows=show.map((x,i)=>`<button class="card uk-stat-mobile-card text-left" onclick="statProfileModal(P(${x.p.id}),${i+1},${x.v})">
   <span class="uk-stat-mobile-rank">${i+1}</span>
   <span class="uk-stat-mobile-photo">${x.p.photo?`<img src="${esc(x.p.photo)}" alt="">`:ini(x.p.n)}</span>
   <span class="uk-stat-mobile-main">
     <span class="uk-stat-mobile-name">${esc(x.p.n)}</span>
     <span class="uk-stat-mobile-meta">${esc(T(x.p.t)?.n||'-')} · ${esc(x.p.playing_role||x.p.role||'-')}</span>
   </span>
   <span class="uk-stat-mobile-value"><strong>${x.v}</strong><span>${statMetricLabel(statMetric)}</span></span>
 </button>`).join('');
 return `<section class="hero p-5 md:p-7 mb-5">
   <div class="text-xs font-extrabold opacity-70">UNITED KERALAM</div>
   <h1 class="text-2xl md:text-4xl font-extrabold mt-1">${t('statistics').toUpperCase()}</h1>
   <p class="mt-1 max-w-2xl text-sm opacity-80">${t('statistics_desc')}</p>
 </section>
 <div class="card p-3 md:p-4 mb-5">
   <div class="flex flex-wrap items-center gap-2 mb-3">
     <div class="text-sm font-extrabold mr-1">${t('format')}:</div>
     ${fmtBtns.map(([v,l])=>`<button class="btn ${statFmt==v?'':'o'} !px-4 !py-2" onclick="statFmt='${v}';render()">${l}</button>`).join('')}
   </div>
   <div class="grid grid-cols-1 sm:grid-cols-[minmax(0,280px)_1fr] gap-3 items-center">
     <select onchange="statTeam=this.value;render()">
       <option value="">${t('all_teams')}</option>
       ${teams.map(x=>`<option value="${x.id}" ${String(statTeam)==String(x.id)?'selected':''}>${esc(x.n)}</option>`).join('')}
     </select>
     <div class="text-xs font-bold" style="color:var(--mut)">👆 ${t('click_for_stats')}</div>
   </div>
 </div>

 <div class="uk-stat-layout">
   <main class="uk-stat-main min-w-0">
     <div class="flex items-end justify-between gap-3 mb-3">
       <div>
         <h2 class="text-xl md:text-2xl font-extrabold">${statMetricLabel(statMetric)}</h2>
         <p class="text-xs mt-1" style="color:var(--mut)">Top 100 players · ${statFmt==='T20I'?'T20':statFmt}${statTeam!==''?' · '+esc(T(+statTeam)?.n||''):''}</p>
       </div>
       <div class="text-xs font-extrabold px-3 py-2 rounded-full shrink-0" style="background:var(--soft);color:var(--mut)">100</div>
     </div>
     <div class="card uk-stat-table-wrap">
       <table class="w-full" style="min-width:700px">
         <thead><tr>
           <th>${t('position').toUpperCase()}</th><th style="text-align:left">PLAYER</th><th>TEAM</th><th>ROLE</th>
           <th>${statMetricLabel(statMetric).toUpperCase()}</th><th>${t('view')||'PROFILE'}</th>
         </tr></thead>
         <tbody>${playerRows||`<tr><td colspan="6" class="p-8 text-center" style="color:var(--mut)">${t('no_stat_data')}</td></tr>`}</tbody>
       </table>
     </div>
     <div class="uk-stat-mobile">
       ${mobileRows||`<div class="card p-8 text-center" style="color:var(--mut)">${t('no_stat_data')}</div>`}
     </div>
   </main>

   <aside class="uk-stat-side">
     <div class="card p-3 mb-2" style="position:sticky;top:0;z-index:2;background:var(--card)">
       <h3 class="text-base font-extrabold">${t('statistics')}</h3>
       <p class="text-[11px] mt-1" style="color:var(--mut)">↕ ${lang()=='ta'?'தனியாக ஸ்க்ரோல் செய்யலாம்':lang()=='ml'?'തനியாக സ്ക്രോൾ ചെയ്യാം':lang()=='hi'?'अलग से स्क्रॉल करें':lang()=='ar'?'مرر بشكل مستقل':'Scroll this list independently'}</p>
     </div>
     <div class="space-y-2">${metricCards}</div>
   </aside>
 </div>`;
}
/* ---------- team profile statistics ---------- */
const TEAM_STAT_FORMATS=['Overall','Test','ODI','T20I'];
const emptyTeamStat=()=>({matches:0,won:0,winPct:0,lost:0,tie:0,draw:0,nr:0,scoreHigh:0,scoreLow:0,concedeHigh:0,concedeLow:0,tossWon:0,batFirst:0,bowlFirst:0});
const teamStatsKey=(tid,fmt,year)=>`${tid}|${fmt}|${year||'All'}`;
function fixtureScoreNum(v){const m=String(v||'').match(/^(\d+)/);return m?+m[1]:null}
function derivedTeamStat(tid,fmt,year){const out=emptyTeamStat(),rows=(S.fixtures||[]).filter(m=>(m.a==tid||m.b==tid)&&(!fmt||fmt==='Overall'||m.fm===fmt)&&(!year||year==='All'||String(m.d||'').slice(0,4)===String(year)));rows.forEach(m=>{const mine=m.a==tid?fixtureScoreNum(m.sa):fixtureScoreNum(m.sb),opp=m.a==tid?fixtureScoreNum(m.sb):fixtureScoreNum(m.sa);if(m.kind==='Result'||m.res){out.matches++;const rn=norm(m.res||''),tn=norm(T(tid)?.n||'');if(rn.includes(tn)&&tn)out.won++;else if(rn.includes('tie'))out.tie++;else if(rn.includes('draw'))out.draw++;else if(rn.includes('nr')||rn.includes('noresult'))out.nr++;else out.lost++}if(mine!=null){out.scoreHigh=Math.max(out.scoreHigh,mine);out.scoreLow=out.scoreLow?Math.min(out.scoreLow,mine):mine}if(opp!=null){out.concedeHigh=Math.max(out.concedeHigh,opp);out.concedeLow=out.concedeLow?Math.min(out.concedeLow,opp):opp}});out.winPct=out.matches?Math.round(out.won/out.matches*1000)/10:0;return out}
function getTeamStat(tid,fmt,year){S.teamStats=S.teamStats||{};const k=teamStatsKey(tid,fmt,year),d=derivedTeamStat(tid,fmt,year);return {...d,...(S.teamStats[k]||{})}}
function teamStatsForm(tid,fmt,year){const o=getTeamStat(tid,fmt,year);guard(()=>form(`Edit team statistics · ${fmt} · ${year||'All'}`,[['Matches','matches',o.matches],['Won','won',o.won],['Lost','lost',o.lost],['Tie','tie',o.tie],['Draw','draw',o.draw],['No Result','nr',o.nr],['Highest scored','scoreHigh',o.scoreHigh],['Lowest scored','scoreLow',o.scoreLow],['Highest conceded','concedeHigh',o.concedeHigh],['Lowest conceded','concedeLow',o.concedeLow],['Toss won','tossWon',o.tossWon],['Bat first','batFirst',o.batFirst],['Bowl first','bowlFirst',o.bowlFirst]],d=>{const x={...o};Object.keys(d).forEach(k=>x[k]=Math.max(0,Math.floor(+d[k]||0)));x.winPct=x.matches?Math.round(x.won/x.matches*1000)/10:0;S.teamStats=S.teamStats||{};S.teamStats[teamStatsKey(tid,fmt,year)]=x;if(ON)return run(api('/api/settings/team_stats','PUT',{value:S.teamStats})).then(render);save();render()}))}
function teamStatsView(tid,years){const yr=teamYear==='All'||years.includes(+teamYear)?teamYear:'All',o=getTeamStat(tid,teamFmt,yr);return `<div class="format-year-bar mb-5"><div class="pill">${TEAM_STAT_FORMATS.map(f=>`<button class="${teamFmt==f?'on':''}" onclick="teamFmt='${f}';render()">${f==='T20I'?'T20':f}</button>`).join('')}</div><select style="width:auto;min-width:130px" onchange="teamYear=this.value;render()"><option value="All" ${yr==='All'?'selected':''}>All years</option>${years.map(y=>`<option value="${y}" ${String(yr)===String(y)?'selected':''}>${y}</option>`).join('')}</select></div>${EDIT?`<div class="team-stat-edit"><button class="btn" onclick="teamStatsForm(${tid},'${teamFmt}','${yr}')">✎ Edit statistics</button></div>`:''}<section class="team-stat-panel"><div class="team-stat-title">${esc(T(tid)?.n||'')} — ${teamFmt==='T20I'?'T20':teamFmt} Statistics</div><div class="overflow-x-auto"><table class="team-stat-table"><thead><tr><th>Matches</th><th>Won</th><th>Win %</th></tr></thead><tbody><tr><td>${o.matches}</td><td>${o.won}</td><td>${Number(o.winPct||0).toFixed(1)} %</td></tr></tbody></table></div><div class="overflow-x-auto mt-7"><table class="team-stat-table"><thead><tr><th>Lost</th><th>Tie</th><th>Draw</th><th>NR</th></tr></thead><tbody><tr><td>${o.lost}</td><td>${o.tie}</td><td>${o.draw}</td><td>${o.nr}</td></tr></tbody></table></div></section><h2 class="team-stat-title">Team Score</h2><section class="team-stat-panel overflow-x-auto"><table class="team-stat-table"><thead><tr><th></th><th>High</th><th>Low</th></tr></thead><tbody><tr><td class="label">Scored</td><td>${o.scoreHigh||'-'}</td><td>${o.scoreLow||'-'}</td></tr><tr><td class="label">Conceded</td><td>${o.concedeHigh||'-'}</td><td>${o.concedeLow||'-'}</td></tr></tbody></table></section><h2 class="team-stat-title">Toss</h2><section class="team-stat-panel overflow-x-auto"><table class="team-stat-table"><thead><tr><th>Toss Won</th><th>Bat First</th><th>Bowl First</th></tr></thead><tbody><tr><td>${o.tossWon}</td><td>${o.batFirst}</td><td>${o.bowlFirst}</td></tr></tbody></table></section></div>`}
