 const tvn=venueOf(x.venue),capName=String(x.captain||'').replace(/\(.*\)/,'').trim(),capP=S.players.find(p=>norm(p.n.replace(/\(.*\)/,''))==norm(capName)||norm(p.n.replace(/\(.*\)/,'')).includes(norm(capName))||norm(capName).includes(norm(p.n.replace(/\(.*\)/,''))));
