 const squad=()=>{const groups=[[t('top_order').toUpperCase(),ps.filter(p=>/^(Batter|WK-Batter)$/i.test((p.role||'').trim()))],[t('bowler').toUpperCase(),ps.filter(p=>/^Bowler$/i.test((p.role||'').trim()))],[t('middle_order').toUpperCase(),ps.filter(p=>/^All-?rounder$/i.test((p.role||'').trim()))]];return `<div class="space-y-8">${groups.map(([title,list])=>`<section><div class="flex items-center justify-between mb-4"><h2 class="text-xl md:text-2xl font-extrabold tracking-tight">${title}</h2><span class="text-xs font-bold" style="color:var(--mut)">${list.length} ${t('players').toLowerCase()}</span></div>${list.length?`<div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">${list.map(pcard).join('')}</div>`:`<div class="card p-5 text-sm" style="color:var(--mut)">${ti('no_players')}</div>`}</section>`).join('')}</div>`};
