 if(ttab=='bat')body=`<div class="${GR}">${lb(t('most_runs'),bl,'r')}${lb(t('highest_score'),bl,'hs')}${lb(t('most_sixes'),bl,'s6')}${lb(t('best_strike_rate'),bl,'sr')}</div>${ttable(id,bl,'bat')}`;
