const saveCfg=n=>{if(ON)return api('/api/settings/footer','PUT',{value:n}).then(load);S.cfg=n;save()};
function footerForm(){guard(()=>{const c=S.cfg||{},l=c.links||{};form('Footer & social links',[['Facebook link','fb',c.fb||''],['YouTube link','yt',c.yt||''],['Instagram link','ig',c.ig||''],['X (Twitter) link','x',c.x||''],['Stumps logo','slogo',c.slogo||'','img'],['Stumps link (opens when the logo is clicked)','surl',c.surl||''],['Copyright text (empty = default)','copy',c.copy||''],['Terms of service link (optional)','terms',l.terms||''],['Privacy policy link (optional)','privacy',l.privacy||''],['Careers link (optional)','careers',l.careers||''],['Related sites link (optional)','related',l.related||'']],d=>{
 ['fb','yt','ig','x','surl','terms','privacy','careers','related'].forEach(k=>{d[k]=d[k].trim();if(d[k]&&!su(d[k]))throw new Error('Links must start with https:// or http://')});
 return saveCfg({...c,fb:d.fb,yt:d.yt,ig:d.ig,x:d.x,slogo:d.slogo||'',surl:d.surl,copy:d.copy.trim(),links:{terms:d.terms,privacy:d.privacy,careers:d.careers,related:d.related},pages:c.pages||{}})})})}
const INFO_T={terms:'Terms of service',privacy:'Privacy policy',careers:'Careers',related:'Related sites',cookie:'Cookie preferences'};
V.info=function(k){if(!INFO_T[k])return'';const b=((S.cfg||{}).pages||{})[k];return`<section class="hero p-8 mb-6"><h1 class="text-3xl font-extrabold">${INFO_T[k]}</h1></section><div class="card p-6"><div style="white-space:pre-wrap;line-height:1.7">${b?esc(b):'<span style="color:var(--mut)">Nothing has been published here yet.</span>'}</div><button class="btn mt-5" onclick="pageForm('${k}')">✎ Edit this page</button></div>`};
